create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create table if not exists public.owner_profiles(user_id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.owner_profiles where user_id=auth.uid()); $$;
revoke all on function public.is_owner() from public; grant execute on function public.is_owner() to anon, authenticated;
create table if not exists public.members(id uuid primary key default gen_random_uuid(), full_name text not null check(length(trim(full_name)) between 2 and 120), phone text not null check(length(phone) between 8 and 20), email text, address text, status text not null default 'active' check(status in ('active','inactive','archived')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists members_phone_unique_active on public.members(phone) where status <> 'archived';
create index if not exists members_name_idx on public.members using gin(to_tsvector('simple',full_name));
create table if not exists public.membership_plans(id uuid primary key default gen_random_uuid(), name text not null, price_inr integer not null check(price_inr>=0), duration_days integer not null check(duration_days between 1 and 3650), duration_label text, description text, benefits jsonb not null default '[]'::jsonb, joining_fee_inr integer not null default 0 check(joining_fee_inr>=0), discount_percent numeric(5,2) not null default 0 check(discount_percent between 0 and 100), is_featured boolean not null default false, is_active boolean not null default true, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.memberships(id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id) on delete restrict, plan_id uuid references public.membership_plans(id) on delete set null, plan_name_snapshot text not null, price_inr integer not null check(price_inr>=0), joining_fee_inr integer not null default 0 check(joining_fee_inr>=0), start_date date not null, end_date date not null, status text not null default 'pending' check(status in ('pending','active','expired','cancelled')), source text not null default 'admin' check(source in ('admin','online_payment','manual_payment')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_date>=start_date));
create index if not exists memberships_member_idx on public.memberships(member_id); create index if not exists memberships_dates_idx on public.memberships(status,end_date);
create table if not exists public.enquiries(id uuid primary key default gen_random_uuid(), full_name text not null check(length(trim(full_name)) between 2 and 120), phone text not null check(length(phone) between 8 and 20), email text, interested_plan text, preferred_start_date date, message text, source text not null default 'website', status text not null default 'new' check(status in ('new','contacted','interested','converted','not_interested','closed')), owner_notes text, consent boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists enquiries_status_idx on public.enquiries(status,created_at desc);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(), member_id uuid references public.members(id) on delete set null, membership_id uuid references public.memberships(id) on delete set null, plan_id uuid references public.membership_plans(id) on delete set null, plan_name_snapshot text not null, amount_inr integer not null check(amount_inr>=0), currency text not null default 'INR' check(currency='INR'), status text not null default 'created' check(status in ('created','authorized','captured','failed','refunded','partially_refunded','manual_paid')), provider text not null default 'razorpay' check(provider in ('razorpay','cash','upi','bank_transfer','other')), razorpay_order_id text unique, razorpay_payment_id text unique, signature_verified boolean not null default false, payment_method text, webhook_event_id text unique, paid_at timestamptz, refunded_amount_inr integer not null default 0 check(refunded_amount_inr between 0 and amount_inr), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists payments_status_date_idx on public.payments(status,paid_at desc);
alter table public.memberships add column if not exists payment_id uuid unique references public.payments(id) on delete set null;
create table if not exists public.gym_hours(id uuid primary key default gen_random_uuid(), day_index integer not null unique check(day_index between 0 and 6), day_of_week text not null, open_time time, close_time time, is_closed boolean not null default false, timezone text not null default 'Asia/Kolkata', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(is_closed or (open_time is not null and close_time is not null and open_time<close_time)));
insert into public.gym_hours(day_index,day_of_week,open_time,close_time,is_closed) values (0,'Sunday','07:00','12:00',false),(1,'Monday','06:00','22:00',false),(2,'Tuesday','06:00','22:00',false),(3,'Wednesday','06:00','22:00',false),(4,'Thursday','06:00','22:00',false),(5,'Friday','06:00','22:00',false),(6,'Saturday','06:00','20:00',false) on conflict(day_index) do nothing;
create table if not exists public.special_closures(id uuid primary key default gen_random_uuid(), title text not null, starts_at timestamptz not null, ends_at timestamptz not null, is_closed boolean not null default true, announcement text, created_at timestamptz not null default now(), check(ends_at>starts_at));
create table if not exists public.gallery_images(id uuid primary key default gen_random_uuid(), image_url text not null, storage_path text, caption text, alt_text text, category text not null default 'gym', display_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.trainers(id uuid primary key default gen_random_uuid(), name text not null, bio text, experience text, specialization text, certifications text, photo_url text, contact_info text, display_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.facilities(id uuid primary key default gen_random_uuid(), name text not null, description text, icon text, display_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.testimonials(id uuid primary key default gen_random_uuid(), customer_name text not null, quote text not null, image_url text, display_order integer not null default 0, is_active boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.website_content(key text primary key, value jsonb not null default 'null'::jsonb, is_public boolean not null default true, updated_at timestamptz not null default now());
insert into public.website_content(key,value) values ('hero_heading','"BUILD YOUR BEST SELF."'),('hero_description','"A stronger body starts with one decision."'),('hero_primary_label','"Join Now"'),('footer_text','"Stronger every day."') on conflict(key) do nothing;
create table if not exists public.social_links(id uuid primary key default gen_random_uuid(), platform text not null, url text not null, is_enabled boolean not null default true, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id) on delete set null, action text not null, entity_type text not null, entity_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.payment_webhook_events(id uuid primary key default gen_random_uuid(), event_id text not null unique, event_type text not null, payload jsonb not null, processed_at timestamptz, created_at timestamptz not null default now());
-- Updated timestamps for editable tables
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['members','membership_plans','memberships','enquiries','payments','gym_hours','gallery_images','trainers','facilities','testimonials','social_links'] LOOP EXECUTE format('drop trigger if exists set_updated_at on public.%I',t); EXECUTE format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); END LOOP; END $$;
-- RLS everywhere. Public content is read-only and explicitly filtered.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['owner_profiles','members','membership_plans','memberships','enquiries','payments','gym_hours','special_closures','gallery_images','trainers','facilities','testimonials','website_content','social_links','audit_logs','payment_webhook_events'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "owner profile self read" on public.owner_profiles for select to authenticated using (user_id=auth.uid() and public.is_owner());
create policy "public active plans read" on public.membership_plans for select to anon,authenticated using (is_active=true);
create policy "owner manage plans" on public.membership_plans for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public gym hours read" on public.gym_hours for select to anon,authenticated using (true);
create policy "owner manage gym hours" on public.gym_hours for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public active gallery read" on public.gallery_images for select to anon,authenticated using (is_active=true);
create policy "owner manage gallery" on public.gallery_images for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public active trainers read" on public.trainers for select to anon,authenticated using (is_active=true);
create policy "owner manage trainers" on public.trainers for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public active facilities read" on public.facilities for select to anon,authenticated using (is_active=true);
create policy "owner manage facilities" on public.facilities for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public active testimonials read" on public.testimonials for select to anon,authenticated using (is_active=true);
create policy "owner manage testimonials" on public.testimonials for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public published website content read" on public.website_content for select to anon,authenticated using (is_public=true);
create policy "owner manage website content" on public.website_content for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "public enabled social links read" on public.social_links for select to anon,authenticated using (is_enabled=true);
create policy "owner manage social links" on public.social_links for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only members" on public.members for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only memberships" on public.memberships for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only enquiries" on public.enquiries for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only payments" on public.payments for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only closures" on public.special_closures for all to authenticated using (public.is_owner()) with check (public.is_owner());
create policy "owner only audit logs" on public.audit_logs for select to authenticated using (public.is_owner());
create policy "owner only webhook events" on public.payment_webhook_events for select to authenticated using (public.is_owner());
-- Storage bucket: public read is necessary for website images; owner-only writes.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('gym-gallery','gym-gallery',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do nothing;
create policy "public read gym gallery" on storage.objects for select to anon,authenticated using (bucket_id='gym-gallery');
create policy "owner upload gym gallery" on storage.objects for insert to authenticated with check (bucket_id='gym-gallery' and public.is_owner());
create policy "owner update gym gallery" on storage.objects for update to authenticated using (bucket_id='gym-gallery' and public.is_owner()) with check (bucket_id='gym-gallery' and public.is_owner());
create policy "owner delete gym gallery" on storage.objects for delete to authenticated using (bucket_id='gym-gallery' and public.is_owner());
